define(["core/ajax"],function(Ajax){return{processResults:function(selector,results){var options=[];results.forEach(function(result){options.push({value:result.id,label:result.name})});return options},transport:function(selector,query,success,failure){var el=document.querySelector(selector);var userid=el.getAttribute("data-userid");var promises=Ajax.call([{methodname:"local_cohort_manager_search_available_cohorts",args:{userid:parseInt(userid),query:query}}]);promises[0].then(success).catch(failure)}}});
